function chunkStrategy(docType: string) {
  return docType === 'guide'
    ? { strategy: 'SEMANTIC', maxTokens: 600, breakpointPercentile: 95 }
    : { strategy: 'FIXED_SIZE', maxTokens: 150, overlapTokens: 20 };
}

