// Before assembling the prompt, cluster candidates by embedding similarity
// and keep one per cluster.
const DEDUP_THRESHOLD = 0.95; // cosine; above this, treat as the same listing
function dedupe(candidates: Candidate[]): Candidate[] {
  // one representative per near-duplicate cluster
  return collapseByCosine(candidates, DEDUP_THRESHOLD);
}

